def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    largest = max(v1, v2, v3)

    return {
        "value": largest,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "largest_provision_for_credit_losses": largest,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
